	@Test
	void binaryRelationTransformRequiresBothPayloadsAndCompleteTopology() {
		LmdbFrontierExactTransformCache cache = new LmdbFrontierExactTransformCache(8, 1, 1024 * 1024L);
		Fixture left = exact(new String[] { "x" }, new long[] { 11L });
		Fixture right = exact(new String[] { "y" }, new long[] { 21L });
		Fixture differentRight = exact(new String[] { "y" }, new long[] { 22L });
		Fixture output = exact(new String[] { "x", "y" }, new long[] { 11L, 21L });
		LmdbFrontierExactTransformCache.Descriptor descriptor = binaryRelationDescriptor(
				left.key(), right.key(), output.key(), "union(left=0>0;right=0>1)", FrontierStateOperation.UNION);

		assertThrows(IllegalArgumentException.class, () -> cache.claim(descriptor, left.snapshot()));
		try (LmdbFrontierExactTransformCache.Claim owner = cache.claim(
				descriptor, left.snapshot(), right.snapshot())) {
			owner.publish(output.snapshot(), FrontierStateOperation.UNION);
		}
		try (LmdbFrontierExactTransformCache.Claim changedPayload = cache.claim(
				descriptor, left.snapshot(), differentRight.snapshot())) {
			assertEquals(LmdbFrontierExactTransformCache.ClaimStatus.OWNER, changedPayload.status());
		}
		LmdbFrontierExactTransformCache.Descriptor changedTopology = binaryRelationDescriptor(
				left.key(), right.key(), output.key(), "union(left=0>1;right=0>0)", FrontierStateOperation.UNION);
		try (LmdbFrontierExactTransformCache.Claim separated = cache.claim(
				changedTopology, left.snapshot(), right.snapshot())) {
			assertEquals(LmdbFrontierExactTransformCache.ClaimStatus.OWNER, separated.status());
		}
		try (LmdbFrontierExactTransformCache.Claim hit = cache.claim(
				descriptor, left.snapshot(), right.snapshot())) {
			assertEquals(LmdbFrontierExactTransformCache.ClaimStatus.HIT, hit.status());
			assertEquals(FrontierStateOperation.UNION, hit.await().operation());
		}
	}

